def transform(grid):
    out=[r[:] for r in grid]
    def cross(a,b,c):
        return (b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])
    for color in set(v for row in grid for v in row)-{0}:
        pts=sorted((r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==color)
        if len(pts)<3: continue
        lo=[]
        for p in pts:
            while len(lo)>1 and cross(lo[-2],lo[-1],p)<=0: lo.pop()
            lo.append(p)
        hi=[]
        for p in reversed(pts):
            while len(hi)>1 and cross(hi[-2],hi[-1],p)<=0: hi.pop()
            hi.append(p)
        hull=lo[:-1]+hi[:-1]
        if len(hull)<3: continue
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if all(cross(hull[i],hull[(i+1)%len(hull)],(r,c))>=0 for i in range(len(hull))): out[r][c]=color
    return out

